"""Deep Fingerprinting, official DFNet (Model_NoDef.py from github.com/deep-fingerprinting/df @38df0c1, unmodified),
loaded through a keras-1 -> tf.keras import shim.  Training settings from ClosedWorld_DF_NoDef.py.
Input: per-turn direction sequences (+1 up / -1 down), LENGTH 5000; 6 edge classes."""
import os, sys, glob, types, json, numpy as np
MODEL_NODEF_SRC = '# DF model used for non-defended dataset\nfrom keras.models import Sequential\nfrom keras.layers import Conv1D, MaxPooling1D, BatchNormalization\nfrom keras.layers.core import Activation, Flatten, Dense, Dropout\nfrom keras.layers.advanced_activations import ELU\nfrom keras.initializers import glorot_uniform\n\nclass DFNet:\n    @staticmethod\n    def build(input_shape, classes):\n        model = Sequential()\n        #Block1\n        filter_num = [\'None\',32,64,128,256]\n        kernel_size = [\'None\',8,8,8,8]\n        conv_stride_size = [\'None\',1,1,1,1]\n        pool_stride_size = [\'None\',4,4,4,4]\n        pool_size = [\'None\',8,8,8,8]\n\n        model.add(Conv1D(filters=filter_num[1], kernel_size=kernel_size[1], input_shape=input_shape,\n                         strides=conv_stride_size[1], padding=\'same\',\n                         name=\'block1_conv1\'))\n        model.add(BatchNormalization(axis=-1))\n        model.add(ELU(alpha=1.0, name=\'block1_adv_act1\'))\n        model.add(Conv1D(filters=filter_num[1], kernel_size=kernel_size[1],\n                         strides=conv_stride_size[1], padding=\'same\',\n                         name=\'block1_conv2\'))\n        model.add(BatchNormalization(axis=-1))\n        model.add(ELU(alpha=1.0, name=\'block1_adv_act2\'))\n        model.add(MaxPooling1D(pool_size=pool_size[1], strides=pool_stride_size[1],\n                               padding=\'same\', name=\'block1_pool\'))\n        model.add(Dropout(0.1, name=\'block1_dropout\'))\n\n        model.add(Conv1D(filters=filter_num[2], kernel_size=kernel_size[2],\n                         strides=conv_stride_size[2], padding=\'same\',\n                         name=\'block2_conv1\'))\n        model.add(BatchNormalization())\n        model.add(Activation(\'relu\', name=\'block2_act1\'))\n\n        model.add(Conv1D(filters=filter_num[2], kernel_size=kernel_size[2],\n                         strides=conv_stride_size[2], padding=\'same\',\n                         name=\'block2_conv2\'))\n        model.add(BatchNormalization())\n        model.add(Activation(\'relu\', name=\'block2_act2\'))\n        model.add(MaxPooling1D(pool_size=pool_size[2], strides=pool_stride_size[3],\n                               padding=\'same\', name=\'block2_pool\'))\n        model.add(Dropout(0.1, name=\'block2_dropout\'))\n\n        model.add(Conv1D(filters=filter_num[3], kernel_size=kernel_size[3],\n                         strides=conv_stride_size[3], padding=\'same\',\n                         name=\'block3_conv1\'))\n        model.add(BatchNormalization())\n        model.add(Activation(\'relu\', name=\'block3_act1\'))\n        model.add(Conv1D(filters=filter_num[3], kernel_size=kernel_size[3],\n                         strides=conv_stride_size[3], padding=\'same\',\n                         name=\'block3_conv2\'))\n        model.add(BatchNormalization())\n        model.add(Activation(\'relu\', name=\'block3_act2\'))\n        model.add(MaxPooling1D(pool_size=pool_size[3], strides=pool_stride_size[3],\n                               padding=\'same\', name=\'block3_pool\'))\n        model.add(Dropout(0.1, name=\'block3_dropout\'))\n\n        model.add(Conv1D(filters=filter_num[4], kernel_size=kernel_size[4],\n                         strides=conv_stride_size[4], padding=\'same\',\n                         name=\'block4_conv1\'))\n        model.add(BatchNormalization())\n        model.add(Activation(\'relu\', name=\'block4_act1\'))\n        model.add(Conv1D(filters=filter_num[4], kernel_size=kernel_size[4],\n                         strides=conv_stride_size[4], padding=\'same\',\n                         name=\'block4_conv2\'))\n        model.add(BatchNormalization())\n        model.add(Activation(\'relu\', name=\'block4_act2\'))\n        model.add(MaxPooling1D(pool_size=pool_size[4], strides=pool_stride_size[4],\n                               padding=\'same\', name=\'block4_pool\'))\n        model.add(Dropout(0.1, name=\'block4_dropout\'))\n\n        model.add(Flatten(name=\'flatten\'))\n        model.add(Dense(512, kernel_initializer=glorot_uniform(seed=0), name=\'fc1\'))\n        model.add(BatchNormalization())\n        model.add(Activation(\'relu\', name=\'fc1_act\'))\n\n        model.add(Dropout(0.7, name=\'fc1_dropout\'))\n\n        model.add(Dense(512, kernel_initializer=glorot_uniform(seed=0), name=\'fc2\'))\n        model.add(BatchNormalization())\n        model.add(Activation(\'relu\', name=\'fc2_act\'))\n\n        model.add(Dropout(0.5, name=\'fc2_dropout\'))\n\n        model.add(Dense(classes, kernel_initializer=glorot_uniform(seed=0), name=\'fc3\'))\n        model.add(Activation(\'softmax\', name="softmax"))\n        return model\n'  # verbatim copy of df/src/Model_NoDef.py
DATA_B64 = {'fw_autogen.npz': '', 'fw_langgraph.npz': '', 'real_m4v3.npz': '', 'real_m8v3.npz': '', 'real_main.npz': '', 'train.npz': ''}
import tensorflow as tf
from tensorflow import keras
# ---- import shim: map keras-1 module paths used by Model_NoDef.py onto tf.keras
L = keras.layers
for name, mod in {"keras.layers.core": L, "keras.layers.advanced_activations": L}.items():
    sys.modules[name] = mod
SRC = glob.glob("/kaggle/input/**/Model_NoDef.py", recursive=True) + glob.glob("/kaggle/src/Model_NoDef.py") + glob.glob("Model_NoDef.py")
import base64
D = "/kaggle/working/df_in"; os.makedirs(D, exist_ok=True)
for _n, _b in DATA_B64.items(): open(f"{D}/{_n}", "wb").write(base64.b64decode(_b))
src = open(SRC[0]).read() if SRC else MODEL_NODEF_SRC
ns = {}; exec(compile(src.replace("keras.layers.core", "keras.layers").replace("keras.layers.advanced_activations", "keras.layers").replace("from keras.", "from tensorflow.keras."), "Model_NoDef.py", "exec"), ns); DFNet = ns["DFNet"]
from sklearn.metrics import f1_score
EDGE = ["start", "sequential", "parallel_fork_join", "transport_retry", "semantic_retry", "sub_agent"]
tr = np.load(f"{D}/train.npz", allow_pickle=True); X, y = tr["X"].astype(np.float32)[..., None], tr["y"]
m = np.isin(y, EDGE); X, y = X[m], np.array([EDGE.index(v) for v in y[m]])
rng = np.random.default_rng(0); idx = rng.permutation(len(y)); nv = len(y) // 10; va, trn = idx[:nv], idx[nv:]
model = DFNet.build(input_shape=(5000, 1), classes=len(EDGE))
model.compile(loss="categorical_crossentropy", optimizer=keras.optimizers.Adamax(learning_rate=0.002, beta_1=0.9, beta_2=0.999, epsilon=1e-08), metrics=["accuracy"])
Y = keras.utils.to_categorical(y, len(EDGE))
model.fit(X[trn], Y[trn], batch_size=128, epochs=30, verbose=2, validation_data=(X[va], Y[va]))
out = []
for f in sorted(glob.glob(f"{D}/*.npz")):
    tag = os.path.basename(f)[:-4]
    if tag == "train": continue
    z = np.load(f, allow_pickle=True); P = model.predict(z["X"].astype(np.float32)[..., None], batch_size=256, verbose=0)
    yhat = list(np.array(EDGE)[P.argmax(1)]) + ["missed"] * len(z["missed"]); yt = list(z["y"]) + list(z["missed"])
    out.append(dict(tag=tag, model="deep_fingerprinting_official", n=len(z["y"]), macroF1=float(f1_score(yt, yhat, labels=EDGE, average="macro", zero_division=0)),
                    **{f"F1_{e}": float(v) for e, v in zip(EDGE, f1_score(yt, yhat, labels=EDGE, average=None, zero_division=0))}))
    print(out[-1], flush=True)
json.dump(out, open("/kaggle/working/df_real_results.json", "w"), indent=1)
